CREATE TABLE `case_study_service_relations` (`case_study_id` INT NOT NULL, `service_id` INT NOT NULL, PRIMARY KEY (`case_study_id`,`service_id`), CONSTRAINT `case_study_service_relations_case_study_id_fkey` FOREIGN KEY (`case_study_id`) REFERENCES `case_studies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `case_study_service_relations_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;